<?php require __DIR__.'/app/bootstrap.php';if(Auth::check())redirect('dashboard.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$n=trim($_POST['name']??'');$em=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';if(mb_strlen($n)<2||!filter_var($em,FILTER_VALIDATE_EMAIL)||strlen($pw)<10)$error='Enter valid name/email and a password of at least 10 characters.';else{try{db()->prepare("INSERT INTO users(name,email,password_hash,role,status,created_at,updated_at) VALUES(?,?,?,'user','active',NOW(),NOW())")->execute([$n,$em,password_hash($pw,PASSWORD_DEFAULT)]);Auth::login($em,$pw);redirect('dashboard.php');}catch(PDOException $e){$error='Unable to create account. Email may already be registered.';}}}$pageTitle='Create account';require __DIR__.'/app/views/header.php';?><main class="auth-wrap"><div class="auth-card"><h1 class="h3 fw-bold">Create your account</h1><p class="text-secondary">Your transcript workspace starts here.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif?><form method="post"><?=csrf_field()?><label class="form-label">Full name</label><input class="form-control mb-3" name="name" required maxlength="120"><label class="form-label">Email address</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Password</label><input class="form-control mb-3" type="password" name="password" minlength="10" required><button class="btn btn-primary w-100">Create account</button></form><p class="small mt-4">Already registered? <a href="<?=e(url('login.php'))?>">Sign in</a></p></div></main><?php require __DIR__.'/app/views/footer.php';?>
